/bin/bash -lc "python - <<'PY'
from PIL import Image
import numpy as np
from collections import deque
im=np.array(Image.open('first_frame.png').convert('RGB'))
# masks components with bbox, area, center
masks={
'dark': im.mean(2)<35,
'blue': (im[:,:,2]>im[:,:,0]*1.3)&(im[:,:,2]>im[:,:,1]*1.15)&(im[:,:,2]>25),
'white': (im.min(2)>170)&(im.max(2)-im.min(2)<60),
'red_dark': (im[:,:,0]>im[:,:,1]*1.8)&(im[:,:,0]>im[:,:,2]*1.8)&(im[:,:,0]<100),
}
try:
 import cv2
 for name,m in masks.items():
  n,l,stats,cents=cv2.connectedComponentsWithStats(m.astype('uint8'),8)
  print('\\n',name,'total',m.sum())
  ids=np.argsort(stats[1:,4])[::-1][:20]+1
  for i in ids:
   x,y,w,h,a=stats[i];
   if a>=3: print(a,(x,y,x+w-1,y+h-1),tuple(np.round(cents[i],1)))
except Exception as e: print(e)
PY"

